function filterSort(rows,f){let out=rows.filter(r=>(f.view==='all'||(f.view==='action'&&(r.needs||r.review))||(f.view==='unanswered'&&r.needs)||(f.view==='all-replies'&&r.replied)||(f.view==='exceptions'&&r.category==='exception'))&&(f.category==='all'||r.category===f.category)&&(f.owner==='all'||r.owner===f.owner)&&(!f.search||(r.email+' '+r.summary+' '+r.threads.map(t=>plain(t.body)).join(' ')).toLowerCase().includes(f.search.toLowerCase())));const waiting=r=>r.waiting_since?Date.parse(r.waiting_since):Infinity;const newest=r=>Date.parse(r.reply_at||'')||0;out.sort((a,b)=>{if(f.sort==='value')return b.cart_total_cents-a.cart_total_cents||a.rank-b.rank;if(f.sort==='newest')return newest(b)-newest(a)||a.rank-b.rank;if(f.sort==='oldest')return waiting(a)-waiting(b)||a.rank-b.rank;return a.priority-b.priority||waiting(a)-waiting(b)||b.cart_total_cents-a.cart_total_cents||a.rank-b.rank;});return out;}
